//! The tap and tool worlds as Rust, generated by wasmtime from `wit/`. Generated code:
//! nothing is written here by hand, and coverage does not count it.

wasmtime::component::bindgen!({
    path: "wit",
    world: "tap",
    imports: { default: async | trappable },
    exports: { default: async },
});

/// The tool world: one synchronous call, outbound HTTP only.
pub mod tool {
    wasmtime::component::bindgen!({
        path: "wit",
        world: "tool",
        exports: { default: async },
    });
}
